from functools import wraps
import threading

class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = {}
        self.freq = defaultdict(int)
        self.lfu = defaultdict(list)
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                self.freq[key] += 1
                self.lfu[self.freq[key]].append(key)
                return self.cache[key]
        return None

    def set(self, key, value):
        with self.lock:
            if key in self.cache:
                self.freq[key] += 1
                self.lfu[self.freq[key]].append(key)
            else:
                if len(self.cache) >= self.maxsize:
                    min_freq = min(self.lfu.keys())
                    while self.lfu[min_freq]:
                        lfu_key = self.lfu[min_freq].pop(0)
                        if lfu_key in self.cache:
                            del self.cache[lfu_key]
                            del self.freq[lfu_key]
                            break
                    if not self.lfu[min_freq]:
                        del self.lfu[min_freq]
                self.cache[key] = value
                self.freq[key] = 1
                self.lfu[1].append(key)

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = LFUCache(maxsize, typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if not typed else (args, tuple(sorted(kwargs.items())))
            result = cache.get(key)
            if result is None:
                result = func(*args, **kwargs)
                cache.set(key, result)
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    first_key = next(iter(self))
    return (first_key, self.pop(first_key))

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

