def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a set of all classes and their bases
    all_classes = set(classes)
    for cls in classes:
        all_classes.update(cls.__bases__)

    # Create a dictionary to store the direct bases of each class
    base_dict = {cls: set(cls.__bases__) for cls in all_classes}

    # Remove redundant bases
    for cls in list(all_classes):
        for base in list(base_dict[cls]):
            if base_dict[base].issubset(base_dict[cls]):
                base_dict[cls].remove(base)

    # Sort the classes by their order in the original list
    ordered_classes = sorted(all_classes, key=lambda x: classes.index(x) if x in classes else float('inf'))

    # Filter out the classes that are not needed
    minimal_classes = []
    for cls in ordered_classes:
        if all(base not in minimal_classes for base in base_dict[cls]):
            minimal_classes.append(cls)

    return minimal_classes

