def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        spec_version = inventory.get('type')
        if spec_version and spec_version in self.supported_versions:
            self.spec_version = spec_version
        else:
            raise ValueError("Invalid or missing type value in inventory")

    for item in inventory:
        self._validate_item(item)

    return True

def _validate_item(self, item):
    """Validate a single item in the inventory."""
    for key, spec in self.spec[self.spec_version].items():
        if key not in item:
            if spec.get('required', False):
                raise ValueError(f"Missing required key '{key}' in item")
            continue

        value = item[key]
        if not isinstance(value, spec['type']):
            raise TypeError(f"Invalid type for key '{key}'. Expected {spec['type']}, got {type(value)}")

        if 'allowed_values' in spec and value not in spec['allowed_values']:
            raise ValueError(f"Invalid value for key '{key}'. Allowed values are {spec['allowed_values']}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        if manifest_file.digest not in digests_used:
            return False
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior must be an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The prior inventory must have the same keys as the current inventory")

    for key in self.inventory:
        if self.inventory[key] != prior.inventory[key]:
            raise ValueError(f"The value for key '{key}' in the prior inventory does not match the current inventory")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        if item['version'] == version:
            for logical_path, content_files in item['files'].items():
                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = set()
                logical_path_map[logical_path].update(content_files)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_name, fixity_info in fixity.items():
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block is not listed in the manifest")

        if not isinstance(fixity_info, dict):
            raise ValueError(f"Fixity info for file '{file_name}' must be a dictionary")

        if 'algorithm' not in fixity_info or 'value' not in fixity_info:
            raise ValueError(f"Fixity info for file '{file_name}' must contain 'algorithm' and 'value' keys")

        if not isinstance(fixity_info['algorithm'], str) or not isinstance(fixity_info['value'], str):
            raise ValueError(f"Fixity 'algorithm' and 'value' for file '{file_name}' must be strings")

def files_list(path):
    """
    Return the files in `path`
    """
    if os.path.isdir(path):
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    else:
        raise NotADirectoryError(f"{path} is not a directory")

