from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        pass

    try:
        from xml.etree import ElementTree as ET
        root = ET.fromstring(document)
        if root.tag.endswith("XRD"):
            result = {}
            for link in root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    if rel not in result:
                        result[rel] = []
                    result[rel].append(href)
            return result
    except ET.ParseError:
        pass

    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        return None
    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        with closing(urllib2.urlopen(url)) as response:
            return response.read()
    except urllib2.URLError:
        return None

