            raise errors.InvalidSchemeError('Unable to resolve default for non-Option type')

        # if there is a default set in the spec, add it to the defaults dict
        if arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]

        # if we have a dict option, resolve the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.get_spec_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults

