def print_deprecation_warning(self, arg, replacement):
    """Prints a deprecation warning for the given argument."""
    print(f"Warning: '{arg}' is deprecated. Please use '{replacement}' instead.")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name in self.options:
        for option in self.options[command_name]:
            if option.name == argument_name:
                return option
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silenced_args = []
    for arg in args:
        if arg.startswith('-'):
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.required_args:
        if arg not in args:
            raise ValueError(f"Missing required argument: {arg}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        max_length = self.parsed_yaml.get('args', {}).get(arg_name, {}).get('max_length')
        if max_length is not None and len(arg_value) > max_length:
            raise ValueError(f"Argument '{arg_name}' exceeds the maximum length of {max_length}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choice_args:
            if arg_value not in self.choice_args[arg_name]:
                raise ValueError(f"Invalid choice for {arg_name}: {arg_value}. Available choices are {self.choice_args[arg_name]}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        min_value = getattr(self, f"{arg_name}_min", None)
        max_value = getattr(self, f"{arg_name}_max", None)
        if min_value is not None and arg_value < min_value:
            raise ValueError(f"{arg_name} must be at least {min_value}")
        if max_value is not None and arg_value > max_value:
            raise ValueError(f"{arg_name} must be at most {max_value}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            custom_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args, custom_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, list):
            for item in var:
                if isinstance(item, dict):
                    vars_dict.update(item)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers.get(parser_name)
    if not parser:
        raise ValueError(f"No parser found for {parser_name}")

    for arg_name, arg_type in parser.arg_types.items():
        if arg_name in values_dict:
            values_dict[arg_name] = arg_type(values_dict[arg_name])

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with the given root.")
    return path[len(root):]
